// Step 2: Content Hash, Deduplication & Candidate Filtering
const crypto = require('crypto');
const response = $input.first().json;
const articles = response.articles || response.data || (Array.isArray(response) ? response : []);

if (!articles || articles.length === 0) {
  return [{
    json: {
      status: 'NO_CANDIDATE',
      message: 'No articles returned by Avalia Solar API',
      timestamp: new Date().toISOString()
    }
  }];
}

// Normalize and hash each article
const candidates = articles.map(art => {
  const title = (art.title || '').trim();
  const slug = (art.slug || '').trim();
  const category = (art.category && art.category.name) ? art.category.name : (art.category || 'Energia Solar');
  const summary = (art.excerpt || art.summary || art.description || '').trim();
  const content = (art.content || art.body || summary).trim();

  const hashInput = `${slug}|${title}`;
  const contentHash = crypto.createHash('sha256').update(hashInput).digest('hex');

  return {
    article_id: art.id,
    title,
    slug,
    category,
    summary,
    content: content.slice(0, 1500),
    canonical_url: `https://www.avaliasolar.com.br/blog/${slug}`,
    content_hash: contentHash,
    published_at: art.published_at || art.created_at || new Date().toISOString()
  };
});

// Pick the freshest valid candidate with title and summary
const bestCandidate = candidates.find(c => c.title.length > 10 && c.summary.length > 20) || candidates[0];

return [{
  json: {
    status: 'CANDIDATE_SELECTED',
    candidate: bestCandidate,
    discovered_at: new Date().toISOString()
  }
}];
